56	/**
57	 * A simple LoadBalancing KMSClientProvider that round-robins requests
58	 * across a provided array of KMSClientProviders. It also retries failed
59	 * requests on the next available provider in the load balancer group. It
60	 * only retries failed requests that result in an IOException, sending back
61	 * all other Exceptions to the caller without retry.
62	 */
63	public class LoadBalancingKMSClientProvider extends KeyProvider implements
64	    CryptoExtension,
65	    KeyProviderDelegationTokenExtension.DelegationTokenExtension {
66	
67	  public static Logger LOG =
68	      LoggerFactory.getLogger(LoadBalancingKMSClientProvider.class);
69	
70	  static interface ProviderCallable<T> {
71	    public T call(KMSClientProvider provider) throws IOException, Exception;
72	  }
