99	  private LoadBalancingKMSClientProvider(URI uri,
100	      KMSClientProvider[] providers, long seed, Configuration conf) {
101	    super(conf);
102	    // uri is the token service so it can be instantiated for renew/cancel.
103	    dtService = KMSClientProvider.getDtService(uri);
104	    // if provider not in conf, new client will alias on uri else addr.
105	    if (KMSUtil.getKeyProviderUri(conf) == null) {
106	      canonicalService = dtService;
107	    } else {
108	      // canonical service (credentials alias) will be the first underlying
109	      // provider's service.  must be deterministic before shuffle so multiple
110	      // calls for a token do not obtain another unnecessary token.
111	      canonicalService = new Text(providers[0].getCanonicalServiceName());
112	    }
113	
114	    // shuffle unless seed is 0 which is used by tests for determinism.
115	    this.providers = (seed != 0) ? shuffle(providers) : providers;
116	    for (KMSClientProvider provider : providers) {
117	      provider.setClientTokenProvider(this);
118	    }
119	    this.currentIdx = new AtomicInteger((int)(seed % providers.length));
120	    int maxNumRetries = conf.getInt(CommonConfigurationKeysPublic.
121	        KMS_CLIENT_FAILOVER_MAX_RETRIES_KEY, providers.length);
122	    int sleepBaseMillis = conf.getInt(CommonConfigurationKeysPublic.
123	        KMS_CLIENT_FAILOVER_SLEEP_BASE_MILLIS_KEY,
124	        CommonConfigurationKeysPublic.
125	            KMS_CLIENT_FAILOVER_SLEEP_BASE_MILLIS_DEFAULT);
126	    int sleepMaxMillis = conf.getInt(CommonConfigurationKeysPublic.
127	        KMS_CLIENT_FAILOVER_SLEEP_MAX_MILLIS_KEY,
128	        CommonConfigurationKeysPublic.
129	            KMS_CLIENT_FAILOVER_SLEEP_MAX_MILLIS_DEFAULT);
130	    Preconditions.checkState(maxNumRetries >= 0);
131	    Preconditions.checkState(sleepBaseMillis >= 0);
132	    Preconditions.checkState(sleepMaxMillis >= 0);
133	    this.retryPolicy = RetryPolicies.failoverOnNetworkException(
134	        RetryPolicies.TRY_ONCE_THEN_FAIL, maxNumRetries, 0, sleepBaseMillis,
135	        sleepMaxMillis);
136	    LOG.debug("Created LoadBalancingKMSClientProvider for KMS url: {} with {} "
137	            + "providers. delegation token service: {}, canonical service: {}",
138	        uri, providers.length, dtService, canonicalService);
139	  }
