146	  @Override
147	  public org.apache.hadoop.security.token.Token<? extends TokenIdentifier>
148	      selectDelegationToken(Credentials creds) {
149	    Token<? extends TokenIdentifier> token =
150	        KMSClientProvider.selectDelegationToken(creds, canonicalService);
151	    if (token == null) {
152	      token = KMSClientProvider.selectDelegationToken(creds, dtService);
153	    }
154	    // fallback to querying each sub-provider.
155	    if (token == null) {
156	      for (KMSClientProvider provider : getProviders()) {
157	        token = provider.selectDelegationToken(creds);
158	        if (token != null) {
159	          break;
160	        }
161	      }
162	    }
163	    return token;
164	  }
