166	  private <T> T doOp(ProviderCallable<T> op, int currPos,
167	      boolean isIdempotent) throws IOException {
168	    if (providers.length == 0) {
169	      throw new IOException("No providers configured !");
170	    }
171	    int numFailovers = 0;
172	    for (int i = 0;; i++, numFailovers++) {
173	      KMSClientProvider provider = providers[(currPos + i) % providers.length];
174	      try {
175	        return op.call(provider);
176	      } catch (AccessControlException ace) {
177	        // No need to retry on AccessControlException
178	        // and AuthorizationException.
179	        // This assumes all the servers are configured with identical
180	        // permissions and identical key acls.
181	        throw ace;
182	      } catch (IOException ioe) {
183	        LOG.warn("KMS provider at [{}] threw an IOException: ",
184	            provider.getKMSUrl(), ioe);
185	        // SSLHandshakeException can occur here because of lost connection
186	        // with the KMS server, creating a ConnectException from it,
187	        // so that the FailoverOnNetworkExceptionRetry policy will retry
188	        if (ioe instanceof SSLHandshakeException) {
189	          Exception cause = ioe;
190	          ioe = new ConnectException("SSLHandshakeException: "
191	              + cause.getMessage());
192	          ioe.initCause(cause);
193	        }
194	        RetryAction action = null;
195	        try {
196	          action = retryPolicy.shouldRetry(ioe, 0, numFailovers, isIdempotent);
197	        } catch (Exception e) {
198	          if (e instanceof IOException) {
199	            throw (IOException)e;
200	          }
201	          throw new IOException(e);
202	        }
203	        // make sure each provider is tried at least once, to keep behavior
204	        // compatible with earlier versions of LBKMSCP
205	        if (action.action == RetryAction.RetryDecision.FAIL
206	            && numFailovers >= providers.length - 1) {
207	          LOG.error("Aborting since the Request has failed with all KMS"
208	              + " providers(depending on {}={} setting and numProviders={})"
209	              + " in the group OR the exception is not recoverable",
210	              CommonConfigurationKeysPublic.KMS_CLIENT_FAILOVER_MAX_RETRIES_KEY,
211	              getConf().getInt(
212	                  CommonConfigurationKeysPublic.
213	                  KMS_CLIENT_FAILOVER_MAX_RETRIES_KEY, providers.length),
214	              providers.length);
215	          throw ioe;
216	        }
217	        if (((numFailovers + 1) % providers.length) == 0) {
218	          // Sleep only after we try all the providers for every cycle.
219	          try {
220	            Thread.sleep(action.delayMillis);
221	          } catch (InterruptedException e) {
222	            throw new InterruptedIOException("Thread Interrupted");
223	          }
224	        }
225	      } catch (Exception e) {
226	        if (e instanceof RuntimeException) {
227	          throw (RuntimeException)e;
228	        } else {
229	          throw new WrapperException(e);
230	        }
231	      }
232	    }
233	  }
