235	  private int nextIdx() {
236	    while (true) {
237	      int current = currentIdx.get();
238	      int next = (current + 1) % providers.length;
239	      if (currentIdx.compareAndSet(current, next)) {
240	        return current;
241	      }
242	    }
243	  }
