251	  public Token<?> getDelegationToken(String renewer) throws IOException {
252	    return doOp(new ProviderCallable<Token<?>>() {
253	      @Override
254	      public Token<?> call(KMSClientProvider provider) throws IOException {
255	        Token<?> token = provider.getDelegationToken(renewer);
256	        // override sub-providers service with our own so it can be used
257	        // across all providers.
258	        token.setService(dtService);
259	        LOG.debug("New token service set. Token: ({})", token);
260	        return token;
261	      }
262	    }, nextIdx(), false);
263	  }
