287	  @Override
288	  public void warmUpEncryptedKeys(String... keyNames) throws IOException {
289	    Preconditions.checkArgument(providers.length > 0,
290	        "No providers are configured");
291	    boolean success = false;
292	    IOException e = null;
293	    for (KMSClientProvider provider : providers) {
294	      try {
295	        provider.warmUpEncryptedKeys(keyNames);
296	        success = true;
297	      } catch (IOException ioe) {
298	        e = ioe;
299	        LOG.error(
300	            "Error warming up keys for provider with url"
301	            + "[" + provider.getKMSUrl() + "]", ioe);
302	      }
303	    }
304	    if (!success && e != null) {
305	      throw e;
306	    }
307	  }
